local clocks={[0.75000000000000000]="0.75",[1.0500000000000000]="1.05",[1.3500000000000001]="1.35",[1.6500000000000001]="1.6500000000000001",[1.9500000000000002]="1.9500000000000002",[2.2500000000000000]="2.25",[2.5499999999999998]="2.55",[2.8499999999999996]="2.8499999999999996",[3.1499999999999995]="3.1499999999999995",[3.4499999999999993]="3.4499999999999993",[3.7499999999999991]="3.749999999999999",[4.0499999999999989]="4.049999999999999",[4.3499999999999988]="4.349999999999999",[4.6499999999999986]="4.649999999999999",[4.9499999999999984]="4.949999999999998",[5.2499999999999982]="5.249999999999998",[5.5499999999999980]="5.549999999999998"}
local M={}
function M.previewStrokeId(cycle,clock) local label=clocks[clock];assert(label,'Unexpected preview stroke clock');return 'preview:'..string.format('%.0f',cycle)..':'..label end
return M
